package com.eatwhat.mapper;

import com.eatwhat.dto.AssistantV4Contract.*;
import org.apache.ibatis.annotations.*;
import java.util.*;

@Mapper
public interface AssistantV4Mapper {
    @Select("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_type='BASE TABLE' AND table_name IN ('assistant_v4_session','assistant_v4_turn','assistant_v4_message')") int installedSchemaTables();
    String SESSION="id,user_id AS userId,workspace_id AS workspaceId,request_id AS requestId,request_hash AS requestHash,created_at AS createdAt,updated_at AS updatedAt";
    String TURN="id,user_id AS userId,session_id AS sessionId,workspace_id AS workspaceId,request_id AS requestId,request_hash AS requestHash,status,CAST(input_json AS CHAR) AS inputJson,CAST(result_json AS CHAR) AS resultJson,CAST(continuation_json AS CHAR) AS continuationJson,lease_token AS leaseToken,lease_until AS leaseUntil,model_deadline_at AS modelDeadlineAt,provider_calls_used AS providerCallsUsed,created_at AS createdAt,updated_at AS updatedAt";
    @Select("SELECT "+SESSION+" FROM assistant_v4_session WHERE user_id=#{user} AND id=#{id}") SessionRecord session(@Param("user") Long user,@Param("id") String id);
    @Select("SELECT "+SESSION+" FROM assistant_v4_session WHERE user_id=#{user} AND request_id=#{request}") SessionRecord sessionByRequest(@Param("user") Long user,@Param("request") String request);
    @Insert("INSERT INTO assistant_v4_session(id,user_id,workspace_id,request_id,request_hash,created_at,updated_at) VALUES(#{id},#{userId},#{workspaceId},#{requestId},#{requestHash},#{createdAt},#{updatedAt})") int insertSession(SessionRecord row);
    @Update("UPDATE assistant_v4_session SET updated_at=#{now} WHERE user_id=#{user} AND id=#{id}") int touchSession(@Param("user") Long user,@Param("id") String id,@Param("now") long now);
    @Select("SELECT "+TURN+" FROM assistant_v4_turn WHERE user_id=#{user} AND id=#{id}") TurnRecord turn(@Param("user") Long user,@Param("id") String id);
    @Select("SELECT "+TURN+" FROM assistant_v4_turn WHERE user_id=#{user} AND session_id=#{session} AND request_id=#{request}") TurnRecord turnByRequest(@Param("user") Long user,@Param("session") String session,@Param("request") String request);
    @Insert("INSERT INTO assistant_v4_turn(id,user_id,session_id,workspace_id,request_id,request_hash,status,input_json,result_json,created_at,updated_at) VALUES(#{id},#{userId},#{sessionId},#{workspaceId},#{requestId},#{requestHash},#{status},#{inputJson},#{resultJson},#{createdAt},#{updatedAt})") int insertTurn(TurnRecord row);
    @Update("UPDATE assistant_v4_turn SET status='running',lease_token=#{lease},lease_until=#{until},model_deadline_at=#{deadline} WHERE user_id=#{user} AND id=#{id} AND status='queued' AND provider_calls_used=0") int acquire(@Param("user") Long user,@Param("id") String id,@Param("lease") String lease,@Param("until") long until,@Param("deadline") long deadline);
    @Update("UPDATE assistant_v4_turn SET provider_calls_used=provider_calls_used+1 WHERE user_id=#{user} AND id=#{id} AND status='running' AND lease_token=#{lease} AND lease_until>#{now} AND model_deadline_at>#{now} AND provider_calls_used<4") int reserve(@Param("user") Long user,@Param("id") String id,@Param("lease") String lease,@Param("now") long now);
    @Update("<script>UPDATE assistant_v4_turn SET status=#{r.status},result_json=#{r.resultJson},continuation_json=#{r.continuationJson},lease_token=#{r.leaseToken},lease_until=#{r.leaseUntil},model_deadline_at=#{r.modelDeadlineAt},updated_at=#{r.updatedAt} WHERE user_id=#{r.userId} AND id=#{r.id} AND status=#{expected}<if test='lease != null'> AND lease_token=#{lease}</if></script>") int save(@Param("r") TurnRecord row,@Param("expected") String expected,@Param("lease") String lease);
    @Insert("INSERT INTO assistant_v4_message(user_id,session_id,turn_id,role,text_content,cards_json,created_at) VALUES(#{user},#{session},#{turn},#{role},#{text},#{cards},#{now})") int message(@Param("user") Long user,@Param("session") String session,@Param("turn") String turn,@Param("role") String role,@Param("text") String text,@Param("cards") String cards,@Param("now") long now);
    @Select("SELECT CAST(id AS CHAR) AS id,turn_id AS turnId,role,text_content AS text,CAST(cards_json AS CHAR) AS cardsJson,created_at AS createdAt FROM assistant_v4_message WHERE user_id=#{user} AND session_id=#{session} AND id<#{before} AND created_at>=#{oldest} ORDER BY id DESC LIMIT #{limit}") List<Map<String,Object>> messages(@Param("user") Long user,@Param("session") String session,@Param("before") long before,@Param("limit") int limit,@Param("oldest") long oldest);
    @Delete("DELETE FROM assistant_v4_message WHERE user_id=#{user} AND session_id=#{session} AND id NOT IN (SELECT id FROM (SELECT id FROM assistant_v4_message WHERE user_id=#{user} AND session_id=#{session} ORDER BY id DESC LIMIT 200) retained)") int trimMessages(@Param("user") Long user,@Param("session") String session);
    @Select("SELECT "+TURN+" FROM assistant_v4_turn WHERE user_id=#{user} AND session_id=#{session} AND status IN ('queued','running','awaiting_confirmation')") List<TurnRecord> activeSessionTurns(@Param("user") Long user,@Param("session") String session);
    @Delete("DELETE FROM assistant_v4_session WHERE user_id=#{user} AND id=#{id}") int deleteSession(@Param("user") Long user,@Param("id") String id);
    @Select("SELECT "+SESSION+" FROM assistant_v4_session WHERE updated_at<#{before} LIMIT 100") List<SessionRecord> idleSessions(@Param("before") long before);
    @Select("SELECT "+TURN+" FROM assistant_v4_turn WHERE status='queued' OR (status='running' AND lease_until<=#{now}) ORDER BY created_at LIMIT 32") List<TurnRecord> recoverable(@Param("now") long now);
    @Select("SELECT "+TURN+" FROM assistant_v4_turn WHERE status IN ('queued','running','awaiting_confirmation') AND (created_at<#{oldest} OR (status='running' AND lease_until<=#{now}) OR (status='awaiting_confirmation' AND COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(result_json,'$.pendingAction.expiresAt')) AS UNSIGNED),updated_at+600000)<=#{now})) ORDER BY created_at LIMIT 100") List<TurnRecord> expiredActiveTurns(@Param("now") long now,@Param("oldest") long oldest);
    @Delete("DELETE FROM assistant_v4_message WHERE created_at<#{before}") int purgeMessageText(@Param("before") long before);
    @Update("UPDATE assistant_v4_turn SET input_json=NULL,result_json=JSON_OBJECT('retryable',false),continuation_json=JSON_REMOVE(continuation_json,'$.steps[0].arguments','$.steps[1].arguments','$.steps[2].arguments') WHERE status NOT IN ('queued','running','awaiting_confirmation') AND updated_at<#{before}") int purgeTerminalInputs(@Param("before") long before);
    @Update("UPDATE assistant_v4_turn SET input_json=NULL,result_json=JSON_OBJECT('retryable',false),continuation_json=JSON_REMOVE(continuation_json,'$.steps[0].arguments','$.steps[1].arguments','$.steps[2].arguments') WHERE status NOT IN ('queued','running','awaiting_confirmation') AND created_at<#{before}") int purgeOldTurnText(@Param("before") long before);
    @Delete("DELETE FROM assistant_v4_turn WHERE status NOT IN ('queued','running','awaiting_confirmation') AND created_at<#{before}") int purgeTerminalMetadata(@Param("before") long before);
}
